1	<script lang="ts">
2	  import { onMount } from 'svelte';
3	  import { apiFetch, ApiError } from '../lib/api';
4	  import { getWorksheetData } from '../lib/tableau';
5	  import { sessionStore } from '../stores/session.svelte';
6	  import { dataStore } from '../stores/data.svelte';
7	
8	  const sessionHeaders = (): Record<string, string> =>
9	    sessionStore.sessionId ? { 'X-Autom9-Session': sessionStore.sessionId } : {};
10	
11	  async function loadWorksheetConfig(): Promise<string | null> {
12	    try {
13	      const config = await apiFetch<{ data: { data_panel?: { worksheet_name?: string } } | null }>(
14	        '/api/config/workflow'
15	      );
16	      return config.data?.data_panel?.worksheet_name ?? null;
17	    } catch {
18	      return null;
19	    }
20	  }
21	
22	  async function loadWorksheetData(worksheetName: string): Promise<void> {
23	    dataStore.worksheetState = 'loading';
24	    try {
25	      dataStore.worksheetRows = await getWorksheetData(worksheetName);
26	      dataStore.worksheetState = 'done';
27	    } catch (err) {
28	      dataStore.worksheetError =
29	        err instanceof Error ? err.message : 'Could not load worksheet data';
30	      dataStore.worksheetState = 'error';
31	    }
32	  }
33	
34	  async function loadTasks(): Promise<void> {
35	    dataStore.tasksState = 'loading';
36	    try {
37	      const response = await apiFetch<{ data: Array<{ text: string }> }>('/api/data/tasks', {
38	        headers: sessionHeaders(),
39	      });
40	      dataStore.tasks = response.data;
41	      dataStore.tasksState = 'done';
42	    } catch (err) {
43	      const msg =
44	        err instanceof ApiError
45	          ? err.message
46	          : err instanceof Error
47	            ? err.message
48	            : 'Could not load task list';
49	      dataStore.tasksError = msg;
50	      dataStore.tasksState = 'error';
51	    }
52	  }
53	
54	  onMount(async () => {
55	    const worksheetName = await loadWorksheetConfig();
56	
57	    // Both fetches run independently — one failure must not block the other (NFR9)
58	    const worksheetPromise = worksheetName
59	      ? loadWorksheetData(worksheetName)
60	      : (() => {
61	          dataStore.worksheetError = 'Worksheet name not configured';
62	          dataStore.worksheetState = 'error';
63	          return Promise.resolve();
64	        })();
65	
66	    await Promise.allSettled([worksheetPromise, loadTasks()]);
67	  });
68	</script>
