75	      <p class="loading">Loading…</p>
76	    {:else if dataStore.worksheetState === 'error'}
77	      <p class="error">{dataStore.worksheetError}</p>
78	    {:else if dataStore.worksheetRows.length === 0}
79	      <p class="empty">No data available</p>
80	    {:else}
81	      <table>
82	        <thead>
83	          <tr>
84	            {#each Object.keys(dataStore.worksheetRows[0]) as col}
85	              <th>{col}</th>
86	            {/each}
87	          </tr>
88	        </thead>
89	        <tbody>
90	          {#each dataStore.worksheetRows as row}
91	            <tr>
92	              {#each Object.values(row) as val}
93	                <td>{val}</td>
94	              {/each}
95	            </tr>
96	          {/each}
97	        </tbody>
98	      </table>
99	    {/if}
100	  </section>
101	
102	  <!-- Task list from Google Docs -->
103	  <section class="panel-section">
104	    <h3>Task List</h3>
105	    {#if dataStore.tasksState === 'loading'}
106	      <p class="loading">Loading…</p>
107	    {:else if dataStore.tasksState === 'error'}
108	      <p class="error">{dataStore.tasksError}</p>
109	    {:else if dataStore.tasks.length === 0}
110	      <p class="empty">No tasks available</p>
111	    {:else}
112	      <ul>
113	        {#each dataStore.tasks as task}
114	          <li>{task.text}</li>
115	        {/each}
116	      </ul>
117	    {/if}
118	  </section>
119	</div>
