1	/**
2	 * Thin wrapper around window.tableau.extensions.initializeAsync().
3	 * Resolves immediately when Tableau runtime is absent (dev/test environment).
4	 */
5	
6	type TableauExtensions = {
7	  extensions: {
8	    initializeAsync: () => Promise<void>;
9	  };
10	};
11	
12	declare global {
13	  interface Window {
14	    tableau?: TableauExtensions;
15	  }
16	}
17	
18	export interface WorksheetRow {
19	  [fieldName: string]: string;
20	}
21	
22	let initialized = false;
23	
24	/**
25	 * Returns the Tableau user identifier from the extension context.
26	 * Falls back to "dev-user" when no Tableau runtime is present (dev/test).
27	 * Must be called AFTER initializeExtension() resolves.
28	 */
29	export function getTableauUserId(): string {
30	  if (typeof window === 'undefined' || !window.tableau) {
31	    return 'dev-user';
32	  }
33	  try {
34	    // tableau.extensions.environment.context is available post-initializeAsync()
35	    const context = (window.tableau.extensions as unknown as {
36	      environment?: { context?: { user?: { userId?: string } } };
37	    }).environment?.context;
38	    return context?.user?.userId ?? 'unknown-user';
39	  } catch {
40	    return 'unknown-user';
41	  }
42	}
43	
44	/**
45	 * Reads summary data from a named Tableau worksheet.
46	 * Returns an array of row objects keyed by field name (formattedValue).
47	 * Throws an Error if the worksheet is not found or data cannot be retrieved.
48	 * Returns [] immediately when no Tableau runtime is present (dev/test).
49	 */
50	export async function getWorksheetData(worksheetName: string): Promise<WorksheetRow[]> {
51	  if (typeof window === 'undefined' || !window.tableau) {
52	    return [];
53	  }
54	
55	  const extensions = window.tableau.extensions as unknown as {
56	    dashboardContent?: {
57	      dashboard?: {
58	        worksheets?: Array<{
59	          name: string;
60	          getSummaryDataAsync: () => Promise<{
61	            columns: Array<{ fieldName: string }>;
62	            data: Array<Array<{ formattedValue: string }>>;
63	          }>;
64	        }>;
65	      };
66	    };
67	  };
68	
69	  const worksheets = extensions.dashboardContent?.dashboard?.worksheets ?? [];
70	  const worksheet = worksheets.find((w) => w.name === worksheetName);
71	  if (!worksheet) {
72	    throw new Error(`Worksheet "${worksheetName}" not found in dashboard`);
73	  }
74	
75	  const dataTable = await worksheet.getSummaryDataAsync();
76	  const columns = dataTable.columns.map((c) => c.fieldName);
77	  return dataTable.data.map((row) =>
78	    Object.fromEntries(columns.map((col, i) => [col, row[i]?.formattedValue ?? '']))
79	  );
80	}
81	
82	export async function initializeExtension(): Promise<void> {
83	  if (typeof window === 'undefined' || !window.tableau) {
84	    // No Tableau runtime — running in dev/test outside Tableau Desktop/Cloud.
85	    // Resolve immediately so the extension shell renders normally.
86	    return;
87	  }
88	  if (initialized) return;
89	  await window.tableau.extensions.initializeAsync();
90	  initialized = true;
91	}
