1	<script lang="ts">
2	  import { onMount } from 'svelte';
3	  import { initializeExtension, getTableauUserId } from './lib/tableau';
4	  import { apiFetch, ApiError } from './lib/api';
5	  import { sessionStore } from './stores/session.svelte';
6	  import { statusStore } from './stores/status.svelte';
7	  import StatusBar from './components/StatusBar.svelte';
8	  import AdminConfig from './components/AdminConfig.svelte';
9	  import DataPanel from './components/DataPanel.svelte';
10	
11	  const isAdminView = new URLSearchParams(window.location.search).has('admin');
12	
13	  type AppStatus = 'loading' | 'ready' | 'error';
14	
15	  let appStatus = $state<AppStatus>('loading');
16	  let errorMessage = $state('');
17	
18	  onMount(async () => {
19	    try {
20	      // Step 1: Initialize Tableau runtime
21	      await initializeExtension();
22	
23	      // Step 2: Get Tableau user identity
24	      const tableauUserId = getTableauUserId();
25	      sessionStore.tableauUserId = tableauUserId;
26	
27	      // Step 3: Create backend session
28	      const sessionResponse = await apiFetch<{
29	        data: { session_id: string; started_at: string };
30	      }>('/api/sessions', {
31	        method: 'POST',
32	        body: JSON.stringify({ tableau_user_id: tableauUserId }),
33	      });
34	      sessionStore.sessionId = sessionResponse.data.session_id;
35	
36	      // Step 4: Fetch integration statuses
37	      statusStore.loading = true;
38	      const sessionHeaders: Record<string, string> = {};
39	      if (sessionStore.sessionId) {
40	        sessionHeaders['X-Autom9-Session'] = sessionStore.sessionId;
41	      }
42	      const statusResponse = await apiFetch<{
43	        data: { integrations: Array<{ name: string; status: string; latency_ms: number | null; error: string | null }> };
44	      }>('/api/status', {
45	        headers: sessionHeaders,
46	      });
47	
48	      statusStore.integrations = statusResponse.data.integrations.map((i) => ({
49	        name: i.name,
50	        status: i.status as 'healthy' | 'unavailable',
51	        latency_ms: i.latency_ms,
52	        error: i.error,
53	      }));
54	      statusStore.loading = false;
55	
56	      appStatus = 'ready';
57	    } catch (err) {
58	      statusStore.loading = false;
59	      const msg = err instanceof Error ? err.message : 'Extension failed to initialize';
60	      errorMessage = msg;
61	      statusStore.error = msg;
62	      appStatus = 'error';
63	    }
64	  });
65	</script>
66	
67	{#if appStatus === 'loading'}
68	  <div class="autom9-loading">
69	    <p>Loading autom9…</p>
70	  </div>
71	{:else if appStatus === 'error'}
72	  <div class="autom9-error">
73	    <p><strong>autom9 failed to load</strong></p>
74	    <p>{errorMessage}</p>
75	  </div>
76	{:else}
77	  <div class="autom9-shell">
78	    <StatusBar />
79	    {#if isAdminView}
80	      <AdminConfig />
81	    {/if}
82	    <DataPanel />
83	    <!-- Chat panel added in Epic 3 story 3.3 -->
84	  </div>
85	{/if}
86	
87	<style>
88	  .autom9-loading,
89	  .autom9-error,
90	  .autom9-shell {
91	    font-family: sans-serif;
92	    min-height: 100vh;
93	  }
94	  .autom9-loading {
95	    padding: 1rem;
96	  }
97	  .autom9-error {
98	    color: #c00;
99	    padding: 1rem;
100	  }
101	</style>
